const painel = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Painel', parameters: { jsCode: "// No 'Painel' do workflow AN · NF-e Focus (emitir e anexar) (s1JHMJosqDcEeWbr), depois do webhook 'Painel API'\n// (POST /webhook/nfe-painel-api). Painel de NF-e da Central Administrativa (card \"Notas Fiscais\", assets/painel-nfe.html).\n// 09/11/2026: o painel mora dentro do workflow do emissor para usar as chaves que ja estao aqui (Focus, token manual,\n// banco), lidas em tempo de execucao do no 'Chaves NF-e (não apagar)'; nao ha copia de chave neste codigo nem credencial nova.\n//\n// Corpo: { k, acao: 'ver'|'emitir', pedido: '16477'|'AN-16477', documento?, ie? }\n//  - ver: pedido na Shopify + situacao da NF-e (nfe_emissoes / Focus).\n//  - emitir sem correcao: chama este mesmo emissor (/webhook/nfe-focus?pedido=...&modo=on).\n//  - emitir com documento e/ou IE: pega o payload que o emissor ja montou (nfe_emissoes.payload), troca o destinatario e\n//    reenvia para a Focus com a mesma ref; grava 'processando' e chama o emissor para acompanhar e anexar no pedido.\n//    Caso de origem: AN-16477, CNPJ de empresa de SP, rejeicao 232 \"IE do destinatario nao informada\".\nconst CHAVE = '<NFE_PAINEL_CHAVE>';\nconst self = this;\nconst fonte = String((($('Chaves NF-e (não apagar)').params) || {}).jsCode || '');\nconst cfg = (k) => { const m = fonte.match(new RegExp('const ' + k + \" = '([^']*)'\")); return m ? m[1] : ''; };\nconst SK = cfg('SK'), SB = cfg('SB'), ADM = cfg('ADM'), FOCUS = cfg('FOCUS'), FOCUS_TOKEN = cfg('FOCUS_TOKEN'), TOKEN_MANUAL = cfg('TOKEN_MANUAL');\nconst responder = (o) => [{ json: o }];\nif (!SK || !SB || !ADM || !FOCUS || !FOCUS_TOKEN || !TOKEN_MANUAL) return responder({ ok: false, erro: 'O painel não conseguiu ler a configuração do emissor.' });\n\n// ---------- entrada ----------\nconst b = ($input.first().json.body) || {};\nif (String(b.k || '') !== CHAVE) return responder({ ok: false, erro: 'Acesso negado. Abra o painel pela Central Administrativa.' });\nlet ped = String(b.pedido || '').toUpperCase().replace(/\\s+/g, '').replace(/^#/, '');\nif (/^\\d+$/.test(ped)) ped = 'AN-' + ped;\nif (!/^AN-\\d{3,7}$/.test(ped)) return responder({ ok: false, erro: 'Número de pedido inválido. Use 16477 ou AN-16477.' });\nconst acao = /^(ver|emitir)$/.test(String(b.acao || '')) ? b.acao : 'ver';\nconst docNovo = String(b.documento || '').replace(/\\D/g, '');\nconst ieNova = String(b.ie || '').trim().toUpperCase().replace(/[^0-9A-Z]/g, '');\n\n// ---------- ajudantes ----------\nconst dig = (s) => String(s == null ? '' : s).replace(/\\D/g, '');\nconst E = (v) => (v === null || v === undefined) ? 'null' : (\"'\" + String(v).replace(/'/g, \"''\") + \"'\");\nasync function sql(q) {\n  const r = await self.helpers.httpRequest({ method: 'POST', url: SB, json: true, timeout: 30000, headers: { apikey: SK, Authorization: 'Bearer ' + SK, 'Content-Type': 'application/json' }, body: { query: q } });\n  if (r && r.error) throw new Error('SQL: ' + String(r.error).slice(0, 300));\n  return Array.isArray(r) ? r : [];\n}\nasync function gql(query, variables) {\n  const resp = await self.helpers.httpRequest({ method: 'POST', url: ADM, json: true, timeout: 60000, headers: { 'User-Agent': 'Mozilla/5.0' },\n    body: { acao: 'atualizar_pedido', endpoint: '../2026-07/graphql.json', metodo: 'POST', payload: { query, variables: variables || {} } } });\n  const d = resp && resp.dados;\n  if (!d || !d.data) throw new Error('Shopify: ' + JSON.stringify((d && d.errors) || resp).slice(0, 300));\n  return d.data;\n}\nasync function focus(method, path, body) {\n  const r = await self.helpers.httpRequest({ method, url: FOCUS + path, json: true, body, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true,\n    headers: { Authorization: 'Basic ' + Buffer.from(FOCUS_TOKEN + ':').toString('base64') } });\n  return { status: r.statusCode, body: r.body || {} };\n}\nasync function robo() {\n  try {\n    return await self.helpers.httpRequest({ method: 'GET', url: 'https://n8n.americanutrition.com/webhook/nfe-focus',\n      qs: { t: TOKEN_MANUAL, pedido: ped, modo: 'on' }, json: true, timeout: 150000 });\n  } catch (e) { return { ok: false, erro: String(e.message).slice(0, 200) }; }\n}\nconst lerNota = async () => (await sql('select pedido, status, mensagem, numero, serie, chave, danfe_url, xml_url, payload from nfe_emissoes where pedido = ' + E(ped)))[0] || {};\n\n// ---------- pedido na Shopify ----------\nconst d = await gql('query($q:String!){ orders(first:3, query:$q){ nodes{ id name createdAt displayFinancialStatus displayFulfillmentStatus cancelledAt'\n  + ' currentTotalPriceSet{ shopMoney{ amount } } shippingAddress{ name city provinceCode } customAttributes{ key value }'\n  + ' localizationExtensions(first:5){ nodes{ purpose title value } } metafields(namespace:\"nfe\", first:10){ nodes{ key value } } } } }', { q: 'name:' + ped });\nconst o = ((d.orders || {}).nodes || []).find((x) => String(x.name).toUpperCase() === ped);\nif (!o) return responder({ ok: false, erro: 'Pedido ' + ped + ' não encontrado na Shopify.' });\nconst mf = {}; (((o.metafields || {}).nodes) || []).forEach((m) => { mf[m.key] = m.value; });\nconst attr = (k) => { const a = (o.customAttributes || []).find((x) => String(x.key).toLowerCase() === k.toLowerCase()); return a ? a.value : ''; };\nlet doc = '';\nfor (const x of ((o.localizationExtensions || {}).nodes || [])) { if (/TAX|CPF|CNPJ/i.test(String(x.purpose) + String(x.title))) doc = dig(x.value); }\nif (!doc) doc = dig(attr('CPF') || attr('CNPJ'));\nconst sa = o.shippingAddress || {};\nconst avisos = [];\nlet row = await lerNota();\n\n// ---------- emitir ----------\nif (acao === 'emitir') {\n  if (mf.danfe_url || row.status === 'autorizado') avisos.push('Este pedido já tem NF-e autorizada.');\n  else if (o.cancelledAt || !/PAID/i.test(o.displayFinancialStatus)) avisos.push('Pedido cancelado ou não pago: a NF-e não é emitida.');\n  else if (!docNovo && !ieNova) { const r = await robo(); if (r && r.ok === false) avisos.push('Emissor: ' + (r.erro || 'falhou')); }\n  else if (!row.payload) {\n    const r = await robo(); if (r && r.ok === false) avisos.push('Emissor: ' + (r.erro || 'falhou'));\n    avisos.push('O pedido ainda não tinha passado pelo emissor. Rodei o emissor normal; se a SEFAZ recusar, mande a correção de novo.');\n  } else if (!/^(erro|revisar|simulado)$/.test(String(row.status))) {\n    avisos.push('A NF-e está em \"' + row.status + '\". A correção só vale para nota recusada ou em revisão.');\n  } else if (row.status === 'revisar' && !String(row.mensagem || '').split('; ').every((m) => /CPF\\/CNPJ/.test(m))) {\n    avisos.push('O pedido tem outros problemas além do documento: ' + row.mensagem + '. Corrija o pedido na Shopify e toque em Gerar NF-e sem correção.');\n  } else {\n    const nf = typeof row.payload === 'string' ? JSON.parse(row.payload) : JSON.parse(JSON.stringify(row.payload));\n    const novoDoc = docNovo || dig(nf.cpf_destinatario || nf.cnpj_destinatario);\n    if (!(novoDoc.length === 11 || novoDoc.length === 14)) avisos.push('CPF/CNPJ inválido: use 11 dígitos (CPF) ou 14 (CNPJ).');\n    else {\n      delete nf.cpf_destinatario; delete nf.cnpj_destinatario; delete nf.inscricao_estadual_destinatario;\n      nf.indicador_inscricao_estadual_destinatario = 9;\n      if (novoDoc.length === 14) nf.cnpj_destinatario = novoDoc; else nf.cpf_destinatario = novoDoc;\n      const desc = ['documento ' + (novoDoc.length === 14 ? 'CNPJ' : 'CPF')];\n      if (novoDoc.length === 14 && ieNova) {\n        if (/^ISENT/.test(ieNova)) { nf.indicador_inscricao_estadual_destinatario = 2; desc.push('IE isento'); }\n        else if (dig(ieNova)) {\n          nf.indicador_inscricao_estadual_destinatario = 1;\n          nf.inscricao_estadual_destinatario = dig(ieNova);\n          desc.push('IE ' + dig(ieNova));\n          // Contribuinte de outro estado nao leva a partilha do DIFAL (EC 87 e para nao contribuinte).\n          if (Number(nf.local_destino) === 2) (nf.items || []).forEach((it) => { Object.keys(it).forEach((k) => {\n            if (/_uf_destino$|_uf_remetente$|^icms_aliquota_interestadual$|^icms_percentual_partilha$/.test(k)) delete it[k]; }); });\n        }\n      }\n      nf.data_emissao = new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 19) + '-03:00';\n      const env = await focus('POST', '/v2/nfe?ref=' + encodeURIComponent(o.name), nf);\n      const bd = env.body || {};\n      const aceito = env.status === 201 || env.status === 202 || /processando|autorizado/.test(String(bd.status || '')) || /already_processed|pending_operation/.test(String(bd.codigo || ''));\n      const msg = aceito ? 'reenviada pelo painel (' + desc.join(', ') + ')'\n        : ('painel: Focus recusou (' + desc.join(', ') + ') HTTP ' + env.status + ' ' + (bd.mensagem || '') + ' ' + JSON.stringify(bd.erros || '')).slice(0, 500);\n      await sql(\"update nfe_emissoes set status = case when status in ('autorizado', 'autorizado_sem_anexo') then status else \" + E(aceito ? 'processando' : 'erro') + ' end, payload = '\n        + E(JSON.stringify(nf)) + '::jsonb, mensagem = ' + E(msg) + ', atualizado_em = now() where pedido = ' + E(o.name));\n      if (aceito) {\n        await new Promise((ok) => setTimeout(ok, 6000));\n        const r = await robo(); if (r && r.ok === false) avisos.push('Emissor: ' + (r.erro || 'falhou'));\n      } else avisos.push('A Focus recusou o reenvio: ' + (bd.mensagem || ('HTTP ' + env.status)));\n    }\n  }\n  row = await lerNota();\n}\n\n// ---------- resposta ----------\nconst out = { ok: true, pedido: o.name, acao, avisos,\n  shopify: { cliente: sa.name || '', cidade: [sa.city, sa.provinceCode].filter(Boolean).join(' / '), total: Number(o.currentTotalPriceSet.shopMoney.amount),\n    pagamento: o.displayFinancialStatus, envio: o.displayFulfillmentStatus, cancelado: !!o.cancelledAt, criado: o.createdAt, documento: doc },\n  nfe: { status: row.status || 'sem registro', mensagem: row.mensagem || '',\n    numero: mf.numero || (row.numero ? row.numero + ' / serie ' + row.serie : ''), chave: mf.chave || row.chave || '',\n    danfe: mf.danfe_url || row.danfe_url || '', xml: row.xml_url || '' } };\n// Nota que ainda nao fechou: situacao na Focus (motivo da recusa da SEFAZ, ou DANFE se acabou de autorizar).\nif (!out.nfe.danfe && row.status && row.status !== 'ignorado') {\n  const c = await focus('GET', '/v2/nfe/' + encodeURIComponent(o.name));\n  const r = c.body || {};\n  if (c.status !== 404) out.focus = { status: r.status || ('http ' + c.status), sefaz: r.status_sefaz || '', mensagem: r.mensagem_sefaz || r.mensagem || '' };\n  if (r.status === 'autorizado' && r.caminho_danfe) { out.nfe.danfe = FOCUS + r.caminho_danfe; out.nfe.xml = FOCUS + r.caminho_xml_nota_fiscal; out.nfe.numero = r.numero + ' / serie ' + r.serie; }\n}\nreturn responder(out);\n" } }, output: [{ ok: true }] });
const cancelHook = trigger({ type: 'n8n-nodes-base.webhook', version: 2.1, config: { name: 'Pedido cancelado (Shopify)', parameters: { httpMethod: 'POST', path: 'nfe-cancelar', responseMode: 'onReceived', options: {} } }, output: [{ body: { name: 'AN-1', admin_graphql_api_id: 'gid://shopify/Order/1', cancelled_at: '2026-01-01T00:00:00Z' } }] });
const cancelCron = trigger({ type: 'n8n-nodes-base.scheduleTrigger', version: 1.3, config: { name: 'Cancelamentos (30 min)', parameters: { rule: { interval: [{ field: 'minutes', minutesInterval: 30 }] } } }, output: [{ timestamp: '2026-01-01T00:00:00Z' }] });
const cancelar = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: 'Cancelar NF-e', parameters: { jsCode: "// No \"Cancelar NF-e\" do workflow AN · NF-e Focus (emitir e anexar) (s1JHMJosqDcEeWbr). 11/11/2026, pedido do Jaderson:\n// pedido cancelado na Shopify -> cancela a NF-e na Focus/SEFAZ, se ainda estiver no prazo (24 h da autorizacao).\n// Entradas:\n//   - Shopify orders/cancelled -> POST /webhook/nfe-cancelar (corpo = pedido). Sem token: o aviso so dispara uma\n//     conferencia; quem decide e a propria Shopify (o pedido precisa estar cancelado de verdade) e a nfe_emissoes.\n//   - Rede de seguranca a cada 30 min: notas autorizadas nas ultimas 30 h cujo pedido foi cancelado.\n// Regras:\n//   - so cancela nota 'autorizado' / 'autorizado_sem_anexo' de pedido com cancelledAt na Shopify;\n//   - pedido ja enviado (fulfillment) nao cancela sozinho: avisa no Telegram (mercadoria saiu, precisa devolucao);\n//   - fora do prazo (mais de PRAZO_H horas desde a emissao) nao tenta: avisa no Telegram para emitir NF-e de entrada\n//     (devolucao) com o contador;\n//   - cada pedido e tratado uma vez (nfe_emissoes.cancel_status); o aviso de fora do prazo nao repete.\n// Modo em serena_config.nfe_cancelar_auto: off | simulacao (so avisa o que faria) | on.\n// Chaves lidas do no 'Chaves NF-e (não apagar)', como no 'Emitir e Anexar'.\nconst _fonte = String((($('Chaves NF-e (não apagar)').params) || {}).jsCode || '');\nconst _chave = (k) => { const m = _fonte.match(new RegExp('const ' + k + \" = '([^']*)'\")); return m ? m[1] : ''; };\nconst SK = _chave('SK');\nconst SB = 'https://supabase.americanutrition.com/pg/query';\nconst ADM = 'https://n8n.americanutrition.com/webhook/shopify-admin';\nconst FOCUS = 'https://api.focusnfe.com.br';\nconst FOCUS_TOKEN = _chave('FOCUS_TOKEN');\nconst TG_BOT = _chave('TG_BOT');\nconst TG_CHAT = '-1003766435449';\nconst PRAZO_H = 23.5; // a SEFAZ aceita cancelamento ate 24 h depois da autorizacao; margem de 30 min\nconst JUSTIFICATIVA = 'Pedido cancelado a pedido do cliente antes do envio da mercadoria.';\nconst self = this;\nif (!SK || !FOCUS_TOKEN) return [{ json: { ok: false, erro: 'chaves do emissor nao encontradas no no Chaves NF-e (não apagar)' } }];\n\nconst E = (v) => (v === null || v === undefined) ? 'null' : (\"'\" + String(v).replace(/'/g, \"''\") + \"'\");\nconst html = (s) => String(s == null ? '' : s).replace(/[<>&]/g, ' ');\nasync function sql(q) {\n  const r = await self.helpers.httpRequest({ method: 'POST', url: SB, json: true, timeout: 30000, headers: { apikey: SK, Authorization: 'Bearer ' + SK, 'Content-Type': 'application/json' }, body: { query: q } });\n  if (r && r.error) throw new Error('SQL: ' + String(r.error).slice(0, 300));\n  return Array.isArray(r) ? r : [];\n}\nasync function gql(query, variables) {\n  const resp = await self.helpers.httpRequest({ method: 'POST', url: ADM, json: true, timeout: 60000, headers: { 'User-Agent': 'Mozilla/5.0' },\n    body: { acao: 'atualizar_pedido', endpoint: '../2026-07/graphql.json', metodo: 'POST', payload: { query: query, variables: variables || {} } } });\n  const d = resp && resp.dados;\n  if (!d || !d.data) throw new Error('Shopify: ' + JSON.stringify((d && d.errors) || resp).slice(0, 300));\n  return d.data;\n}\nasync function focus(method, path, body) {\n  const r = await self.helpers.httpRequest({ method: method, url: FOCUS + path, json: true, body: body, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true,\n    headers: { Authorization: 'Basic ' + Buffer.from(FOCUS_TOKEN + ':').toString('base64') } });\n  return { status: r.statusCode, body: r.body || {} };\n}\nasync function alerta(texto) {\n  try { await self.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + TG_BOT + '/sendMessage', json: true, timeout: 10000,\n    body: { chat_id: TG_CHAT, parse_mode: 'HTML', disable_web_page_preview: true, text: texto } }); } catch (e) {}\n}\nasync function marcar(pedido, st, extra) {\n  await sql('update nfe_emissoes set cancel_status = ' + E(st) + ', cancel_em = now()'\n    + (extra && extra.cancelado ? \", status = 'cancelado'\" : '')\n    + (extra && extra.resposta ? ', resposta = coalesce(resposta, \\'{}\\'::jsonb) || jsonb_build_object(\\'cancelamento\\', ' + E(JSON.stringify(extra.resposta)) + '::jsonb)' : '')\n    + ', atualizado_em = now() where pedido = ' + E(pedido));\n}\n\nconst ent = $input.first().json || {};\nconst corpo = (ent.body && typeof ent.body === 'object') ? ent.body : {};\nconst evShopify = !!(corpo.admin_graphql_api_id && corpo.name);\n\nconst cfg = {};\n(await sql(\"select chave, valor from serena_config where chave in ('nfe_cancelar_auto')\")).forEach((x) => { cfg[x.chave] = x.valor; });\nconst modo = String(cfg.nfe_cancelar_auto || 'off');\nif (modo === 'off') return [{ json: { ok: true, modo: modo, nada: true } }];\n\n// notas candidatas: a do aviso, ou as autorizadas nas ultimas 30 h ainda nao tratadas\nlet rows;\nif (evShopify) {\n  if (!corpo.cancelled_at) return [{ json: { ok: true, ignorado: 'aviso sem cancelled_at', pedido: corpo.name } }];\n  rows = await sql(\"select pedido, shopify_order_id, status, numero, serie, criado_em from nfe_emissoes where pedido = \" + E(String(corpo.name).trim().toUpperCase())\n    + \" and status in ('autorizado', 'autorizado_sem_anexo') and cancel_status is null\");\n} else {\n  rows = await sql(\"select pedido, shopify_order_id, status, numero, serie, criado_em from nfe_emissoes where status in ('autorizado', 'autorizado_sem_anexo')\"\n    + \" and cancel_status is null and criado_em > now() - interval '30 hours' and shopify_order_id is not null order by criado_em limit 100\");\n}\nif (!rows.length) return [{ json: { ok: true, modo: modo, candidatas: 0 } }];\n\n// situacao de cada pedido na Shopify (a fonte da verdade e a Shopify, nao o aviso)\nconst gid = (id) => /^gid:/.test(String(id)) ? String(id) : 'gid://shopify/Order/' + String(id).replace(/\\D/g, '');\nconst ids = rows.filter((r) => r.shopify_order_id).map((r) => gid(r.shopify_order_id));\nconst situ = {};\nfor (let i = 0; i < ids.length; i += 50) {\n  const d = await gql('query($ids:[ID!]!){ nodes(ids:$ids){ ... on Order { id name cancelledAt cancelReason displayFulfillmentStatus } } }', { ids: ids.slice(i, i + 50) });\n  (d.nodes || []).forEach((o) => { if (o && o.name) situ[String(o.name).toUpperCase()] = o; });\n}\n\nconst saida = { ok: true, modo: modo, candidatas: rows.length, itens: [] };\nfor (const r of rows) {\n  const o = situ[String(r.pedido).toUpperCase()];\n  if (!o || !o.cancelledAt) continue; // pedido nao cancelado: nada a fazer\n  const nota = 'NF-e ' + html(r.numero) + (r.serie ? '/' + html(r.serie) : '');\n  const horas = (Date.now() - new Date(r.criado_em).getTime()) / 3600000;\n  const enviado = /FULFILLED|PARTIAL/i.test(String(o.displayFulfillmentStatus || '')) && !/UNFULFILLED/i.test(String(o.displayFulfillmentStatus || ''));\n  if (enviado) {\n    if (modo === 'on') await marcar(r.pedido, 'enviado_alertado');\n    await alerta('⚠️ <b>Pedido cancelado já enviado</b>: ' + html(r.pedido) + ' (' + nota + ').\\nA nota não foi cancelada automaticamente porque a mercadoria saiu. Ver com o contador a NF-e de devolução.');\n    saida.itens.push({ pedido: r.pedido, resultado: 'ja_enviado' });\n    continue;\n  }\n  if (horas > PRAZO_H) {\n    if (modo === 'on') await marcar(r.pedido, 'fora_prazo');\n    await alerta('⚠️ <b>NF-e fora do prazo de cancelamento</b>: ' + html(r.pedido) + ' (' + nota + '), emitida há ' + Math.round(horas) + ' h.\\nA SEFAZ só cancela até 24 h. Precisa de NF-e de entrada (devolução): falar com o contador.');\n    saida.itens.push({ pedido: r.pedido, resultado: 'fora_prazo', horas: Math.round(horas) });\n    continue;\n  }\n  if (modo !== 'on') {\n    await alerta('🧪 <b>Simulação</b>: cancelaria a ' + nota + ' do pedido ' + html(r.pedido) + ' (cancelado na Shopify, emitida há ' + Math.round(horas * 10) / 10 + ' h).');\n    saida.itens.push({ pedido: r.pedido, resultado: 'simulado' });\n    continue;\n  }\n  const resp = await focus('DELETE', '/v2/nfe/' + encodeURIComponent(r.pedido), { justificativa: JUSTIFICATIVA });\n  const b = resp.body || {};\n  const ok = resp.status < 300 && (b.status === 'cancelado' || String(b.status_sefaz || '') === '135' || String(b.status_sefaz || '') === '155');\n  if (ok) {\n    await marcar(r.pedido, 'cancelado', { cancelado: true, resposta: b });\n    await alerta('🧾❌ <b>NF-e cancelada</b>: ' + nota + ' do pedido ' + html(r.pedido) + ' (pedido cancelado na Shopify). SEFAZ ' + html(b.status_sefaz || '') + ' ' + html(b.mensagem_sefaz || ''));\n    saida.itens.push({ pedido: r.pedido, resultado: 'cancelado', sefaz: b.status_sefaz });\n  } else {\n    await marcar(r.pedido, 'erro', { resposta: { http: resp.status, body: b } });\n    await alerta('⚠️ <b>Falha ao cancelar NF-e</b>: ' + nota + ' do pedido ' + html(r.pedido) + '.\\nFocus ' + resp.status + ': ' + html(b.mensagem_sefaz || b.mensagem || JSON.stringify(b).slice(0, 200)) + '\\nCancelar à mão na Focus enquanto estiver dentro das 24 h.');\n    saida.itens.push({ pedido: r.pedido, resultado: 'erro', http: resp.status });\n  }\n}\nreturn [{ json: saida }];\n" } }, output: [{ ok: true }] });
const painelResp = node({ type: 'n8n-nodes-base.respondToWebhook', version: 1.5, config: { name: 'Painel Responder', parameters: { respondWith: 'json', responseBody: '={{ JSON.stringify($json) }}', options: { responseHeaders: { entries: [{ name: 'Access-Control-Allow-Origin', value: '*' }] } } } } });

const nota = sticky('## NF-e pela Focus\n\nNa hora (POST /webhook/nfe-focus-evento): aviso da Shopify (orders/create e orders/paid) emite a nota do pedido; aviso da Focus (gatilho nfe) anexa a nota autorizada. A cada 60 min, rede de seguranca: acompanha as notas em processamento (autorizada = DANFE e XML anexados no pedido da Shopify, metafields nfe.*, tag NF-e) e emite as dos pedidos pagos e nao enviados desde serena_config.nfe_desde. Modo em serena_config.nfe_modo (off / simulacao / on). Manual: GET /webhook/nfe-focus?t=TOKEN&pedido=AN-123&modo=on. Controle em nfe_emissoes.', [emitir], { color: 4 });

export default workflow('an-nfe-focus', 'AN · NF-e Focus (emitir e anexar)', { settings: { executionOrder: 'v1' } })
  .add(eventos).to(emitir).add(cron).to(emitir).add(manual).to(emitir).add(painelApi).to(painel).to(painelResp).add(cancelHook).to(cancelar).add(cancelCron).to(cancelar).add(chaves).add(nota);
